// Healthy Living lessons 6–10: mental health, wellness through the lifespan, disease prevention,
// the SMART goal and portfolio, and the Round Two presentation.
const RULES=['HOSA Healthy Living 2026–27 guidelines and rating sheet','https://hosa.org/wp-content/uploads/2026/08/Healthy-Living-26-27.pdf'];
const NASM=['National Academy of Sports Medicine (NASM)','https://www.nasm.org/'];
const NIMH=['National Institute of Mental Health: Health topics','https://www.nimh.nih.gov/health/topics'];
const LIFELINE=['988 Suicide & Crisis Lifeline','https://988lifeline.org/'];
const HP=['ODPHP: Healthy People 2030','https://odphp.health.gov/healthypeople'];
const LIFE=['OpenStax Psychology: Lifespan theories','https://openstax.org/books/psychology/pages/9-2-lifespan-theories'];
const CHRONIC=['CDC: Chronic disease','https://www.cdc.gov/chronic-disease/index.html'];
const APA=['APA Style: References','https://apastyle.apa.org/style-grammar-guidelines/references'];
const q=(p,a,b,c,d,e)=>[p,[a,b,c,d],e];
